"""Writes docs/RANKINGS.md from the ranking outputs, so every number in the text is read from the files."""
import os, json, pandas as pd, numpy as np
HERE=os.path.dirname(os.path.abspath(__file__)); OUT=os.path.join(HERE,'..','output'); RK=os.path.join(OUT,'rankings'); DOCS=os.path.join(HERE,'..','docs')
M=pd.read_csv(os.path.join(RK,'mobility_summary.csv')); CL=pd.read_csv(os.path.join(RK,'rank_changes_by_period.csv')); WIN=pd.read_csv(os.path.join(RK,'rank_changes_three_year_windows.csv'))
R=pd.read_csv(os.path.join(RK,'rankings_district_long.csv')); key=json.load(open(os.path.join(RK,'headline_numbers.json'))); adj=pd.read_csv(os.path.join(RK,'adjacent_to_big_cities.csv')).iloc[:,0].tolist()
def nice(u): return u.replace(' DISTRICT','').title()
def row(ser,meas,var,period):
    s=M[(M.series==ser)&(M.measure==meas)&(M.variant==var)&M.year.astype(str).str.contains(period)]; return s.iloc[0]
n=key['n_units']
L=['# District rankings by night-time light, 1992 to 2025: are districts stuck?\n',
   f"Built {pd.Timestamp.today():%d %B %Y} by code/07_district_rankings.py; this note is generated by code/08_rankings_report.py from the files in output/rankings, so the numbers below are the files' numbers.\n",
   '## What was done',
   f"Units are the Census 2023 districts of the four provinces plus Islamabad, with Karachi's seven districts counted as one unit: {n['i_all']} units. Three rankings are built for every year: (i) all {n['i_all']}; (ii) {n['ii_no_big5']} after dropping Islamabad, Lahore, Peshawar, Quetta and Karachi; (iii) {n['iii_no_big5_or_adjacent']} after also dropping the {len(adj)} districts whose boundary touches one of those five ({', '.join(nice(a) for a in adj)}).",
   'Each ranking is computed for three measures: the sum of lights (radiance times area, the size of a district\'s lit economy), light per square kilometre (intensity), and light per thousand people in the three census years. Rank 1 is the brightest; districts with identical values (in practice, zero light in the early years) share the lowest rank of the tied group. Both source series are used: series B (NPP-VIIRS-like radiance, 1992-2025) as the main series and series A (harmonized DMSP digital numbers, 1992-2024) as the check. The file output/rankings/rankings_district_long.csv holds every rank; ranks_wide_*.csv are the same with one column per year.',
   'Two cautions shape how the results are read. Both series are noisiest around the switch from DMSP to VIIRS inputs (2011-2016), so changes are measured within sensor eras (1992-2010 and 2017 onward) as well as end to end, and climbers are confirmed on three-year window means (1992-94 against 2023-25) rather than single years. And a rank is relative: a district can climb because it grew or because others stalled.\n',
   '## Headline answer']
b=row('B','size','iii_no_big5_or_adjacent','end to end'); b1=row('B','size','i_all','end to end'); bd=row('B','size','iii_no_big5_or_adjacent','DMSP era'); bv=row('B','size','iii_no_big5_or_adjacent','VIIRS era')
a=row('A','size','iii_no_big5_or_adjacent','end to end')
L.append(f"The ranking is sticky but not frozen. In ranking (iii), the Spearman correlation between the 1992 and 2025 rankings by sum of lights is {b.spearman_vs_first_year:.2f} (series B; {a.spearman_vs_first_year:.2f} in series A), {b.share_same_quintile:.0%} of districts are in the same quintile in 2025 as in 1992, and the average district moved {b.mean_abs_rank_change:.1f} places out of {int(b.n_units)}. Within the DMSP era (1992 to 2010) the correlation is {bd.spearman_vs_first_year:.2f} and within the VIIRS era (2017 to 2025) {bv.spearman_vs_first_year:.2f}. Including the big cities changes little (ranking (i): correlation {b1.spearman_vs_first_year:.2f}, {b1.share_same_quintile:.0%} same quintile).")
L.append(f"Against that stability, a small group of districts moved a long way. Over 1992 to 2025 in ranking (iii), {int(b.climbers_20_or_more)} districts climbed 20 or more places and {int(b.fallers_20_or_more)} fell 20 or more. Several of the biggest climbers are districts where a large mining, power or port installation is known to have been built in the period; a few are not (section below).\n")
L.append('## The climbers (series B, sum of lights, ranking iii)')
c=CL[(CL.series=='B')&(CL.measure=='size')&(CL.variant=='iii_no_big5_or_adjacent')&(CL.period=='end to end')].sort_values('places_climbed',ascending=False)
w=WIN[(WIN.series=='B')&(WIN.measure=='size')&(WIN.variant=='iii_no_big5_or_adjacent')].set_index('unit')
L.append('| District | Province | Rank 1992 | Rank 2025 | Places climbed | Same on 3-year windows (1992-94 to 2023-25) |'); L.append('|---|---|---|---|---|---|')
for _,x in c.head(12).iterrows(): L.append(f"| {nice(x.unit)} | {x.province.title()} | {x.rank_from} | {x.rank_to} | {x.places_climbed} | {w.loc[x.unit,'rank_1992_94']} to {w.loc[x.unit,'rank_end_window']} ({w.loc[x.unit,'places_climbed']:+d}) |")
L.append('\nThe same names appear whichever way the change is measured. Several of the climbers are districts where a large installation is known to have been built or expanded in the period (Thar coal mining and power generation in Tharparkar, the port works at Gwadar, the Dasu dam site in Upper Kohistan, the Saindak mine and the Reko Diq works in Chagai, the Nashpa and Makori oil and gas fields in Karak). That is a reading of the list against general knowledge, not something these data establish, and it is the obvious first hypothesis to test: a single bright installation can move a sparsely populated district a long way in a ranking by total light. Narowal, Mandi Bahauddin, Swat and Mansehra do not fit that pattern and deserve a closer look.\n')
L.append('## The fallers (series B, sum of lights, ranking iii)')
L.append('| District | Province | Rank 1992 | Rank 2025 | Places fallen | Same on 3-year windows |'); L.append('|---|---|---|---|---|---|')
for _,x in c.tail(8).iloc[::-1].iterrows(): L.append(f"| {nice(x.unit)} | {x.province.title()} | {x.rank_from} | {x.rank_to} | {-x.places_climbed} | {w.loc[x.unit,'rank_1992_94']} to {w.loc[x.unit,'rank_end_window']} ({w.loc[x.unit,'places_climbed']:+d}) |")
L.append('\nThe fallers are frontier districts of Khyber Pakhtunkhwa (Tank, Kurram, Bannu) and parts of northern Sindh (Jacobabad, Naushahro Feroze). Falling in rank does not mean getting darker in absolute terms: almost every district is brighter in 2025 than in 1992.\n')
L.append('## Light per person (census years only)')
pc=R[(R.series=='B')&(R.measure=='percap')&(R.variant=='iii_no_big5_or_adjacent')]
W=pc.pivot(index='unit',columns='year',values='rank')
if 1998 in W.columns and 2023 in W.columns:
    ch=(W[1998]-W[2023]).dropna().sort_values(ascending=False); sp=W[[1998,2023]].dropna().corr(method='spearman').iloc[0,1]
    L.append(f"Ranking districts by light per thousand people in 1998 and 2023 (ranking iii, {int(W[2023].notna().sum())} districts): Spearman correlation {sp:.2f}. Biggest climbers: "+', '.join(f'{nice(u)} ({int(W.loc[u,1998])} to {int(W.loc[u,2023])})' for u in ch.head(8).index)+'. Biggest fallers: '+', '.join(f'{nice(u)} ({int(W.loc[u,1998])} to {int(W.loc[u,2023])})' for u in ch.tail(5).index)+'. Per-person ranks reward sparsely populated districts with a single large installation, so they should be read next to the size ranking rather than instead of it.\n')
L.append('## How much the two satellite series agree')
L.append(f"In 2023 the ranking by sum of lights (all units) has a Spearman correlation of {key['series_agreement_2023_size_all']:.2f} between series A and series B. Mobility is somewhat larger in series A end to end (correlation {a.spearman_vs_first_year:.2f} against {b.spearman_vs_first_year:.2f}) because series A's VIIRS-converted years carry a faint floor that lifts dim districts; within eras the two agree closely. The full table for every series, measure, variant and era is output/rankings/mobility_summary.csv.\n")
L.append('## Figures (output/figures)')
L.append('- fig1_rank_stability_spearman.png: Spearman correlation of each year\'s ranking with 1992, for the three rankings (series B, sum of lights).')
L.append('- fig2_quintile_transitions_1992_2025.png: where districts of each 1992 quintile ended up in 2025 (ranking iii).')
L.append('- fig3_biggest_climbers_rank_paths.png: rank paths 1992-2025 of the eight biggest climbers and four biggest fallers against all other districts (ranking iii).')
L.append('- fig4_rank_1992_vs_2025_scatter.png: every district\'s 2025 rank against its 1992 rank.')
L.append('- fig5_biggest_climbers_density.png: the same as fig3 for light per square kilometre.\n')
L.append('## Files')
L.append('rankings_district_long.csv (every rank), ranks_wide_<series>_<measure>.csv, mobility_summary.csv (Spearman by year and by era, quintile persistence, mean absolute rank change, counts of big movers), rank_changes_by_period.csv (every district\'s change in each era), rank_changes_three_year_windows.csv, transition_quintiles_*.csv (5 x 5 transition counts), adjacent_to_big_cities.csv, headline_numbers.json.')
open(os.path.join(DOCS,'RANKINGS.md'),'w').write('\n'.join(L)+'\n'); print('wrote docs/RANKINGS.md')
